  args: WorkContextReadArgs,
  dependencies: { stateRoot?: string; now?: () => string } = {},
): Promise<CallToolResult> {
  try {
    const binding = await requireWorkContextBinding({
      bindingId: args.bindingId,
      stateRoot: dependencies.stateRoot,
